#include <cstdio>

int main()
{
    int white = 0, black = 0;

    for (int i = 0; i < 8; ++i)
    {
        char line[9];
        if (scanf("%8s", line) != 1)
            return 0;

        for (int j = 0; j < 8; ++j)
        {
            switch (line[j])
            {
                case 'q': black += 9; break;
                case 'r': black += 5; break;
                case 'b':
                case 'n': black += 3; break;
                case 'p': black += 1; break;
                case 'Q': white += 9; break;
                case 'R': white += 5; break;
                case 'B':
                case 'N': white += 3; break;
                case 'P': white += 1; break;
            }
        }
    }

    if (white > black)
        printf("White\n");
    else if (black > white)
        printf("Black\n");
    else
        printf("Draw\n");

    return 0;
}

